-- Nuvora multi-storefront studios (additive and repeatable).
-- Each vertical has independent published config/catalog and a private draft snapshot.
alter table public.store_settings
  add column if not exists games_site_config jsonb not null default '{"version":1,"accentColor":"#a8f45c","announcement":"Good gear. Better sessions. Find your next upgrade.","heroTitle":"Play your way.","heroDescription":"Explore gaming PCs, consoles, peripherals and setup essentials selected for the way you play.","heroImage":"https://images.unsplash.com/photo-1593640408182-31c70c8268f5?auto=format&fit=crop&w=1800&q=85","approachTitle":"Built around your play.","approachBody":"Nuvora Games brings together gaming hardware and setup essentials so you can compare options and find the gear that fits your space, play style and budget.","sections":[{"id":"hero","type":"hero","visible":true},{"id":"categories","type":"category-grid","visible":true},{"id":"featured","type":"product-grid","visible":true},{"id":"approach","type":"editorial","visible":true},{"id":"guides","type":"journal-grid","visible":true}]}'::jsonb,
  add column if not exists games_site_draft jsonb,
  add column if not exists games_products jsonb not null default '[]'::jsonb,
  add column if not exists home_site_config jsonb not null default '{"version":1,"accentColor":"#637b56","announcement":"Thoughtful pieces for the everyday spaces you call home.","heroTitle":"A home that feels like you.","heroDescription":"Discover considered decor, useful appliances and everyday home essentials for rooms that work beautifully and feel personal.","heroImage":"https://images.unsplash.com/photo-1616486338812-3dadae4b4ace?auto=format&fit=crop&w=1800&q=85","approachTitle":"Good living, thoughtfully chosen.","approachBody":"Nuvora Home brings decor, furniture and useful appliances into one considered place.","sections":[{"id":"hero","type":"hero","visible":true},{"id":"categories","type":"category-grid","visible":true},{"id":"featured","type":"product-grid","visible":true},{"id":"approach","type":"editorial","visible":true},{"id":"guides","type":"journal-grid","visible":true}]}'::jsonb,
  add column if not exists home_site_draft jsonb,
  add column if not exists home_products jsonb not null default '[]'::jsonb,
  add column if not exists clothing_site_config jsonb not null default '{"version":1,"accentColor":"#7e3345","announcement":"Everyday staples. Standout pieces. Your own kind of style.","heroTitle":"Get dressed like yourself.","heroDescription":"Explore wearable essentials, statement pieces, shoes and accessories for the many ways you show up.","heroImage":"https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1800&q=85","approachTitle":"Pieces for your point of view.","approachBody":"Nuvora Clothing is a curated place to explore apparel, footwear and accessories across everyday, formal and active wardrobes.","sections":[{"id":"hero","type":"hero","visible":true},{"id":"categories","type":"category-grid","visible":true},{"id":"featured","type":"product-grid","visible":true},{"id":"approach","type":"editorial","visible":true},{"id":"guides","type":"journal-grid","visible":true}]}'::jsonb,
  add column if not exists clothing_site_draft jsonb,
  add column if not exists clothing_products jsonb not null default '[]'::jsonb;

notify pgrst, 'reload schema';
